import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		Scanner sc = new Scanner(System.in);
		int s = sc.nextInt();
		while(s-- > 0){
		    int n = sc.nextInt();
		    int size = 3*n;
		    int[] a = new int[size];
		    for(int i=0;i<size;i++){
		        a[i] = sc.nextInt();
		    }
		    Arrays.sort(a);
		    long[] pre = new long[size+1];
		    for(int i=0;i<size;i++){
		        pre[i+1]=pre[i]+ a[i];
		    }
		    long ans =0;
		    long total = pre[size];
		    for(int A =0 ; A<=n ; A++){
		        
		        int left =0;
		        int right = n-A;
		        while(left < right){
		            int B = (left + right)/2;
		            int q = A+ 2*B;
		            int m = size-2*A-B;
		            long change = (long) a[size - q -2] + a[size - q-1] - 3L * a[size-m];
		            if (change >= 0){
		                left = B+1;
		            }
		            else{
		                right = B;
		            }
		        }
		            int B = left;
		            int q = A+2*B;
		            int m = size-2*A-B;
		            long topA = total - pre[size-A];
		            long topQ = total - pre[size-q];
		            long topM = total - pre[size-m];
		            long cur = 6L * topA + 4L * (topQ - topA) + 3L * (topM - topQ);
		            ans = Math.max(ans,cur);
		            
		        
		        
		    }
		    System.out.println(ans);
		    
		}

	}
}
